"use client";
import Component from "../smoothui/PriceFlow";
import { useState } from "react";
import { DemoFrame } from "../shared/DemoFrame";
export default function Demo() {
  const [yearly, setYearly] = useState(false);
  return (
    <DemoFrame hint={yearly ? "Billed yearly" : "Billed monthly"}>
      <div className="text-center">
        <p className="mb-4 text-xs text-muted-foreground">Studio plan · example pricing</p>
        <div className="flex items-baseline justify-center text-6xl font-semibold">
          <span>$</span>
          <Component value={yearly ? 288 : 29} />
        </div>
        <button className="demo-action mt-8" onClick={() => setYearly(!yearly)}>
          {yearly ? "Show monthly" : "Show yearly"}
        </button>
      </div>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

